/*
  CYBER TEAM HELP - ESP32-S3 Wi-Fi Scanner
  Developer: SHADOW JOKER
  Board: ESP32-S3 Dev Module (Arduino-ESP32 core)
  Purpose: Passive nearby Wi-Fi network scan + local animated dashboard.
  Note: This is source code (.ino), not a precompiled firmware (.bin).
*/

#include <WiFi.h>
#include <WebServer.h>

static const char* AP_SSID = "CTH-ESP32-S3";
static const char* AP_PASSWORD = "CTHscan2026"; // Change before sharing/using publicly.
WebServer server(80);

const char PAGE[] PROGMEM = R"CTH_PAGE(
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#050812">
<title>Cyber Team Help | Wi-Fi Scanner</title>
<style>
:root{--cyan:#00f5ff;--pink:#ff3cac;--green:#8bffb0;--bg:#050812}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(circle at 15% 5%,#102a45 0,transparent 38%),radial-gradient(circle at 90% 20%,#35113b 0,transparent 35%),var(--bg);color:#eafcff;font-family:system-ui,-apple-system,Segoe UI,sans-serif;min-height:100vh}
.wrap{max-width:1000px;margin:auto;padding:18px}
header,.panel{border:1px solid #1a5267;background:#081320d9;box-shadow:0 0 24px #00eaff12;border-radius:18px}
header{padding:20px;text-align:center;position:relative;overflow:hidden}
h1{margin:8px 0;color:var(--cyan);font-size:clamp(24px,5vw,42px);letter-spacing:2px;text-shadow:0 0 18px #00f5ff77}
.sub{color:#b9d9e7}
.pill{display:inline-block;border:1px solid #00f5ff88;color:var(--green);border-radius:999px;padding:6px 12px;font-size:12px;letter-spacing:1px}
.hero{display:flex;align-items:center;justify-content:center;gap:16px;flex-wrap:wrap;margin:18px 0}
.bot{font-size:70px;display:inline-block;filter:drop-shadow(0 0 14px #00f5ff77);animation:float 2.4s ease-in-out infinite}
.bot span{display:block;font-size:11px;color:var(--pink);letter-spacing:2px;text-align:center}
@keyframes float{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-10px) rotate(3deg)}}
@keyframes blink{0%,90%,100%{opacity:1}95%{opacity:.45}}
.scanline{height:3px;background:linear-gradient(90deg,transparent,var(--cyan),var(--pink),transparent);animation:blink 2s infinite;margin-top:18px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:14px 0}
.panel{padding:16px;margin-top:14px}
.stat{font-size:27px;color:var(--cyan);font-weight:800}
.label{font-size:12px;color:#8cb3c8;text-transform:uppercase;letter-spacing:1px}
button{background:linear-gradient(120deg,#00bcd4,#1678ff);border:0;border-radius:12px;padding:12px 16px;color:#001019;font-weight:800;cursor:pointer;box-shadow:0 0 15px #00eaff25}
button:disabled{opacity:.5;cursor:wait}
.actions{display:flex;gap:10px;flex-wrap:wrap}
.secondary{background:#162638;color:#d8f8ff;border:1px solid #286176}
table{width:100%;border-collapse:collapse;min-width:600px}
th,td{text-align:left;padding:11px 9px;border-bottom:1px solid #173345;font-size:13px}
th{color:var(--cyan);position:sticky;top:0;background:#0a1926}
.tablebox{overflow:auto;border-radius:12px}
.meter{height:7px;background:#14283a;border-radius:99px;overflow:hidden;min-width:70px}
.meter i{display:block;height:100%;background:linear-gradient(90deg,#ff5470,#ffda69,#69ffb1);border-radius:99px}
footer{text-align:center;color:#7796a9;font-size:12px;padding:22px}
.credit{color:var(--pink);font-weight:800;letter-spacing:2px}
#status{color:var(--green);margin-top:12px;font-size:13px}
.notice{font-size:12px;color:#91afc0;line-height:1.6}
@media(max-width:600px){.wrap{padding:10px}.panel{padding:12px}th,td{padding:9px 7px}}
</style>
</head>
<body>
<div class="wrap">
<header>
  <div class="pill">● LOCAL DEVICE • ESP32-S3</div>
  <div class="hero"><div class="bot" aria-label="animated robot">🤖<span>CTH BOT</span></div><div>
    <h1>CYBER TEAM HELP</h1>
    <div class="sub">Wi-Fi Scanner // Signal Observatory</div>
    <div class="credit">DEVELOPER: SHADOW JOKER</div>
  </div></div>
  <div class="scanline"></div>
</header>
<div class="grid">
  <div class="panel"><div class="label">Networks detected</div><div class="stat" id="count">—</div></div>
  <div class="panel"><div class="label">Strongest signal</div><div class="stat" id="strongest">—</div></div>
  <div class="panel"><div class="label">Last scan</div><div class="stat" id="last" style="font-size:18px">Not scanned</div></div>
</div>
<div class="panel">
  <div class="actions">
    <button id="scan" onclick="scanNow()">⌁ SCAN WI-FI</button>
    <button class="secondary" onclick="loadData()">↻ REFRESH</button>
    <button class="secondary" onclick="exportCSV()">⇩ EXPORT CSV</button>
  </div>
  <div id="status">Ready. Connect only to networks you own or are authorized to inspect.</div>
</div>
<div class="panel">
  <h3 style="color:var(--cyan);margin-top:0">Nearby networks</h3>
  <div class="tablebox"><table><thead><tr><th>SSID</th><th>RSSI</th><th>Signal</th><th>Channel</th><th>Security</th></tr></thead>
  <tbody id="rows"><tr><td colspan="5">Press SCAN WI-FI to begin.</td></tr></tbody></table></div>
  <p class="notice">This scanner lists broadcast network metadata only. It does not reveal Wi-Fi passwords or inspect other users' traffic.</p>
</div>
<footer>CYBER TEAM HELP • Built for ESP32-S3<br><span class="credit">SHADOW JOKER</span></footer>
</div>
<script>
let current=[];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function securityName(n){return ({0:'Open',1:'WEP',2:'WPA/PSK',3:'WPA2/PSK',4:'WPA/WPA2',5:'WPA2 Enterprise',6:'WPA3/PSK',7:'WPA2/WPA3'})[n]||'Protected';}
async function loadData(){
 try{let r=await fetch('/api/scan');if(!r.ok)throw Error('HTTP '+r.status);let d=await r.json();render(d.networks||[]);document.getElementById('status').textContent='Scan data loaded.';}
 catch(e){document.getElementById('status').textContent='Could not load scan data: '+e.message;}
}
async function scanNow(){
 const b=document.getElementById('scan');b.disabled=true;b.textContent='SCANNING…';document.getElementById('status').textContent='Scanning nearby broadcast networks…';
 try{
   let r=await fetch('/api/scan?refresh=1');if(!r.ok)throw Error('HTTP '+r.status);
   let d=await r.json();
   for(let i=0;d.scanning && i<20;i++){await new Promise(resolve=>setTimeout(resolve,500));r=await fetch('/api/scan');d=await r.json();}
   render(d.networks||[]);document.getElementById('status').textContent=d.scanning?'Scan is still running; press refresh shortly.':'Scan complete.';
 }catch(e){document.getElementById('status').textContent='Scan failed: '+e.message;}
 finally{b.disabled=false;b.textContent='⌁ SCAN WI-FI';}
}
function render(arr){
 current=arr;document.getElementById('count').textContent=arr.length;
 let max=arr.reduce((m,n)=>Math.max(m,n.rssi),-999);
 document.getElementById('strongest').textContent=arr.length?max+' dBm':'—';
 document.getElementById('last').textContent=new Date().toLocaleTimeString();
 const rows=document.getElementById('rows');
 if(!arr.length){rows.innerHTML='<tr><td colspan="5">No networks found. Try scanning again.</td></tr>';return;}
 rows.innerHTML=arr.map(n=>{let pct=Math.max(0,Math.min(100,2*(n.rssi+100)));return `<tr><td>${esc(n.ssid||'(hidden SSID)')}</td><td>${n.rssi} dBm</td><td><div class="meter"><i style="width:${pct}%"></i></div></td><td>${n.channel}</td><td>${esc(securityName(n.auth))}</td></tr>`}).join('');
}
function exportCSV(){
 let lines=[['SSID','RSSI dBm','Channel','Security code'],...current.map(n=>[n.ssid,n.rssi,n.channel,n.auth])];
 let csv=lines.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
 let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='cth-wifi-scan.csv';a.click();URL.revokeObjectURL(a.href);
}
loadData();
</script>
</body></html>
)CTH_PAGE";

String authName(wifi_auth_mode_t auth) {
  switch (auth) {
    case WIFI_AUTH_OPEN: return "Open";
    case WIFI_AUTH_WEP: return "WEP";
    case WIFI_AUTH_WPA_PSK: return "WPA-PSK";
    case WIFI_AUTH_WPA2_PSK: return "WPA2-PSK";
    case WIFI_AUTH_WPA_WPA2_PSK: return "WPA/WPA2-PSK";
    case WIFI_AUTH_WPA2_ENTERPRISE: return "WPA2-Enterprise";
    case WIFI_AUTH_WPA3_PSK: return "WPA3-PSK";
    case WIFI_AUTH_WPA2_WPA3_PSK: return "WPA2/WPA3-PSK";
    default: return "Protected";
  }
}

String scanJson() {
  int n = WiFi.scanComplete();
  if (n == WIFI_SCAN_RUNNING) return "{\"scanning\":true,\"networks\":[]}";
  if (n == WIFI_SCAN_FAILED || n < 0) return "{\"scanning\":false,\"networks\":[]}";
  String out = "{\"scanning\":false,\"networks\":[";
  for (int i = 0; i < n; i++) {
    if (i) out += ",";
    String ssid = WiFi.SSID(i);
    ssid.replace("\\", "\\\\");
    ssid.replace("\"", "\\\"");
    ssid.replace("\n", " ");
    out += "{\"ssid\":\"" + ssid + "\",";
    out += "\"rssi\":" + String(WiFi.RSSI(i)) + ",";
    out += "\"channel\":" + String(WiFi.channel(i)) + ",";
    out += "\"auth\":" + String((int)WiFi.encryptionType(i)) + "}";
  }
  out += "]}";
  WiFi.scanDelete();
  return out;
}

void handleRoot() {
  server.send_P(200, "text/html; charset=utf-8", PAGE);
}

void handleScan() {
  bool refresh = server.hasArg("refresh") && server.arg("refresh") == "1";
  if (refresh) {
    WiFi.scanDelete();
    WiFi.scanNetworks(true, true); // asynchronous scan
    server.send(200, "application/json; charset=utf-8", R"JSON({"scanning":true,"networks":[]})JSON");
    return;
  }
  server.send(200, "application/json; charset=utf-8", scanJson());
}

void setup() {
  Serial.begin(115200);
  delay(300);
  WiFi.mode(WIFI_AP_STA);
  WiFi.setSleep(false);
  bool apOk = WiFi.softAP(AP_SSID, AP_PASSWORD);
  if (!apOk) Serial.println("Warning: SoftAP start failed.");
  Serial.print("Dashboard AP: "); Serial.println(AP_SSID);
  Serial.print("Password: "); Serial.println(AP_PASSWORD);
  Serial.print("Open: http://"); Serial.println(WiFi.softAPIP());

  server.on("/", HTTP_GET, handleRoot);
  server.on("/api/scan", HTTP_GET, handleScan);
  server.onNotFound([](){ server.send(404, "text/plain", "Not found"); });
  server.begin();
}

void loop() {
  server.handleClient();
  delay(2);
}
